"""Exercise actual fullscreen policy against fake Android windows; no device UI."""
from pathlib import Path
import subprocess,tempfile
root=Path(__file__).resolve().parent
sources={
'android/graphics/Color.java':'package android.graphics;public class Color {public static final int TRANSPARENT=0;}',
'android/os/Looper.java':'package android.os;public class Looper {public static Looper getMainLooper(){return new Looper();}}',
'android/os/Handler.java':'''package android.os;public class Handler {public static Runnable pending;public Handler(Looper l){}public void removeCallbacks(Runnable r){if(pending==r)pending=null;}public boolean postDelayed(Runnable r,long ms){if(ms!=100)throw new AssertionError();pending=r;return true;}public static void run(){Runnable r=pending;pending=null;if(r!=null)r.run();}}''',
'android/view/WindowManager.java':'package android.view;public interface WindowManager {class LayoutParams {public static final int FLAG_FULLSCREEN=0x400;}}',
'android/view/View.java':'''package android.view;public class View {public static final int SYSTEM_UI_FLAG_FULLSCREEN=4,SYSTEM_UI_FLAG_HIDE_NAVIGATION=2,SYSTEM_UI_FLAG_IMMERSIVE_STICKY=0x1000,SYSTEM_UI_FLAG_LAYOUT_STABLE=0x100,SYSTEM_UI_FLAG_LAYOUT_FULLSCREEN=0x400,SYSTEM_UI_FLAG_LAYOUT_HIDE_NAVIGATION=0x200;public interface OnSystemUiVisibilityChangeListener {void onSystemUiVisibilityChange(int visibility);}public OnSystemUiVisibilityChangeListener listener;public int flags,sets;public boolean focused=true;public boolean hasWindowFocus(){return focused;}public int getSystemUiVisibility(){return flags;}public void setSystemUiVisibility(int f){sets++;flags=f;if(listener!=null)listener.onSystemUiVisibilityChange(f);}public void setOnSystemUiVisibilityChangeListener(OnSystemUiVisibilityChangeListener l){listener=l;}public void externalFlags(int f){flags=f;if(listener!=null)listener.onSystemUiVisibilityChange(f);}}''',
'android/view/Window.java':'''package android.view;public class Window {public final View decor=new View();public int flags,statusColor=0xff757575;public View getDecorView(){return decor;}public void addFlags(int f){flags|=f;}public void setStatusBarColor(int c){statusColor=c;}}''',
'local/wallpanel/app/FullscreenHarness.java':'''package local.wallpanel.app;import android.view.*;import android.os.Handler;public class FullscreenHarness {static void check(boolean b){if(!b)throw new AssertionError();}public static void main(String[] args){Window w=new Window(),other=new Window();DashboardFullscreen ui=new DashboardFullscreen(w);check((w.flags&0x400)!=0&&w.statusColor==0&&w.decor.flags==0x1706);ui.resume();w.decor.externalFlags(0x1700);check(Handler.pending!=null);Handler.run();check(w.decor.flags==0x1706&&Handler.pending==null);int writes=w.decor.sets;ui.apply();check(w.decor.sets==writes);w.decor.externalFlags(0x1700);ui.pause();check(Handler.pending==null);Handler.run();check(w.decor.flags==0x1700);ui.resume();check(w.decor.flags==0x1706);w.decor.focused=false;w.decor.externalFlags(0x1700);check(Handler.pending==null);w.decor.focused=true;ui.focus(true);check(w.decor.flags==0x1706);w.decor.externalFlags(0x1700);check(Handler.pending!=null);w.decor.focused=false;Handler.run();check(w.decor.flags==0x1700);ui.close();check(w.decor.listener==null&&Handler.pending==null);writes=w.decor.sets;ui.focus(true);ui.apply();ui.resume();check(w.decor.sets==writes);check(other.flags==0&&other.statusColor==0xff757575&&other.decor.sets==0);System.out.println("PASS: native fullscreen/transparent bar, cleared-flag recovery, no recursive writes, pause/focus guards, cleanup and other-window isolation.");}}'''
}
with tempfile.TemporaryDirectory(dir=root/'test-classes',prefix='fullscreen-') as folder:
    temp=Path(folder);files=[]
    for name,body in sources.items():
        p=temp/name;p.parent.mkdir(parents=True,exist_ok=True);p.write_text(body);files.append(p)
    java=r'C:\Program Files (x86)\Java\jre1.8.0_431\bin\java.exe';out=temp/'classes';out.mkdir()
    subprocess.run([java,'-jar',str(root.parent/'audio/tooling/ecj.jar'),'-encoding','UTF-8','-1.8','-nowarn','-d',str(out),str(root/'src/local/wallpanel/app/DashboardFullscreen.java'),*[str(p) for p in files]],check=True)
    subprocess.run([java,'-cp',str(out),'local.wallpanel.app.FullscreenHarness'],check=True,timeout=10)
